    qs_vec_copy(&sorted, values);
    qs_sort_doubles(sorted.v, sorted.len);
    int ordered = sorted.v[0] == out->min && sorted.v[sorted.len - 1] == out->max;
    assert(ordered);
    out->median = qs_median_sorted(sorted.v, sorted.len);
